export type RemoteRoute = "lan" | "tailscale";

export type RemoteSshConfigStatus = "missing" | "present";

export type RemoteSshHostTrust = {
	token: string,
	alias: string,
	hostname: string,
	port: number,
	fingerprints: string[],
};

export type RemoteState = "connecting" | "connected" | "offline" | "disabled" | "error";

export type RemoteSync = "idle" | "catching_up" | "current" | "unavailable";

export type SamplingPatch = {
	interval_ms?: number | null,
	slow_on_battery?: boolean | null,
	performance_mode?: boolean | null,
};

/**
 *  The sampling plan for one combination of settings and power state (D-092). The table
 *  covers the whole input domain, so the Settings panel can show what another choice
 *  would do ("on battery it would be...") by reading a row.
 */
export type SamplingPlan = {
	interval_ms: number,
	slow_on_battery: boolean,
	/**
	 *  Performance mode in effect. The engine turns it on under Low Power Mode, so rows
	 *  with `low_power_mode` and without `performance` never run: they say what the mode
	 *  changes there.
	 */
	performance: boolean,
	low_power_mode: boolean,
	ac: PlanFigures,
	battery: PlanFigures,
};

export type SamplingSettings = {
	/**  Base tick; one of [`SamplingSettings::INTERVALS_MS`] (0.5 s to 60 s). */
	interval_ms: number,
	/**  On battery (or Low Power Mode) the base tick doubles, capped at 60 s. */
	slow_on_battery: boolean,
	/**
	 *  Performance mode (D-088): the background and visible levers that trade update
	 *  rate and motion for CPU. Low Power Mode turns it on too, without changing this
	 *  value; [`PerformanceReason::resolve`] gives the effective state. Absent from a
	 *  settings file written before it existed: off.
	 */
	performance_mode?: boolean,
};

/**
 *  `sensor_dump` (v1-local-monitor.md 4.17). No serial numbers, user names, host names or
 *  network identifiers.
 */
export type SensorDump = {
	model: string | null,
	chip: string | null,
	os_version: string,
	chip_known: boolean,
	capabilities: Capabilities,
	/**
	 *  Every Power and Sensors series in the current layout with its latest value
	 *  (`null` when stale), in layout order.
	 */
	sensors: SensorReading[],
};

export type SensorReading = {
	key: SeriesKey,
	value: number | null,
};

/**
 *  One series: a metric plus its labels. Display form `cpu.load{core=7}`.
 *
 *  On the wire and over IPC it is a struct `{ metric, labels }`; keys always travel as
 *  strings, never as a store's interned IDs.
 */
export type SeriesKey = {
	metric: MetricId,
	labels: Labels,
};

/**  Picks series by metric and a label subset. Used by alert rules and history queries. */
export type SeriesSelector = {
	metric: MetricId,
	/**  Empty matches any labels. Otherwise every pair must appear in the series' labels. */
	labels: Labels,
};

/**  `query_series_stats`: unlabelled metrics over a range, from their rollups through now. */
export type SeriesStats = {
	/**
	 *  The range the stats cover: the request widened to whole buckets of the tier that
	 *  answered and cut at now.
	 */
	from_ms: number,
	to_ms: number,
	/**  One per metric asked for, in order. */
	metrics: MetricStat[],
};

export type Settings = {
	remote_access?: RemoteAccessSettings,
	docker?: DockerSettings,
	/**
	 *  One entry per settings module: every [`Module`] except `Sensors`. An entry for a
	 *  module this build does not know (a settings file from a newer build) is dropped on
	 *  decode (D-040).
	 */
	modules: Partial<{ [key in Module]: ModuleSettings }>,
	/**  Absent from a settings file written before D-102: the default menu bar. */
	menu_bar?: MenuBarSettings,
	sampling: SamplingSettings,
	history: HistorySettings,
	units: UnitSettings,
	general: GeneralSettings,
	onboarding: OnboardingSettings,
	/**  Absent from a settings file written before v1.2: both alerts off. */
	alerts?: AlertSettings,
};

/**  Emitted after every settings change, with the full new settings. */
export type SettingsChanged = {
	revision: number,
	settings: Settings,
};

/**  A partial change. Every field is optional; absent fields keep their value. */
export type SettingsPatch = {
	remote_access?: RemoteAccessPatch | null,
	docker?: DockerSettings | null,
	modules?: Partial<{ [key in Module]: ModulePatch }> | null,
	menu_bar?: MenuBarPatch | null,
	sampling?: SamplingPatch | null,
	history?: HistoryPatch | null,
	units?: UnitsPatch | null,
	general?: GeneralPatch | null,
	onboarding?: OnboardingPatch | null,
	alerts?: AlertsPatch | null,
};

/**
 *  Settings with the revision they were current at. Revisions increase by one per change
 *  within an app run; a window drops a `settings-changed` event older than what it holds.
 */
export type SettingsSnapshot = {
	revision: number,
	settings: Settings,
};

/**  What to ask of the process. */
export type SignalKind =
/**  `NSRunningApplication.terminate` for a regular app, `SIGTERM` otherwise. */
"quit" |
/**  `NSRunningApplication.forceTerminate` for a regular app, `SIGKILL` otherwise. */
"force_quit";

/**  Why Kelvo will not signal a process. The UI words it (`process-signal.ts`). */
export type SignalRefusal =
/**  The macOS kernel (pid 0), or a pid kill(2) would treat as a process group. */
"kernel_task" | "launchd" | "window_server" | "login_window" |
/**  Kelvo itself or one of its helpers. */
"kelvo";

export type SpaceCrumb = {
	id: number,
	name: string,
};

export type SpaceFile = {
	/**  Index for `reveal`. */
	index: number,
	name: string,
	/**  Parent folder relative to the volume root, with "/" separators. */
	parent: string,
	bytes: number | null,
};

export type SpaceKind = "folder" | "file" |
/**  Children too small to show, merged into one entry. */
"smaller" |
/**  Another volume in the same APFS container (System, VM, Preboot...). */
"volume" |
/**
 *  Used space no measured file or volume accounts for: snapshots, APFS metadata,
 *  unreadable and skipped folders, unmounted volumes. Not measured, so drawn as a gap.
 */
"other";

/**  One entry in a folder's breakdown. */
export type SpaceNode = {
	/**  Stable within one report. Synthetic entries (smaller, volumes, other) have none. */
	id: number | null,
	name: string,
	kind: SpaceKind,
	/**  Allocated bytes. For an unfinished folder, what was measured so far. */
	bytes: number | null,
	/**  Files below this entry (merged entries: how many were merged). */
	items: number | null,
	/**  The folder's subtree is completely measured. */
	done: boolean,
	/**  It can be opened: a finished or in-progress folder with a breakdown. */
	openable: boolean,
	/**
	 *  For a folder listed in a `SpaceSubtree`: its own largest entries, at most
	 *  `SPACE_PREVIEW` with the rest merged, so a treemap can draw two levels. A
	 *  subfolder holding 90% or more of it previews its own entries the same way (up to
	 *  three levels). Empty everywhere else.
	 */
	children: SpaceNode[],
};

export type SpacePhase = "idle" | "scanning" | "done" | "cancelled" | "failed";

/**  A privacy-protected location (TCC) that a default scan does not enter. */
export type SpaceProtected = {
	/**  Path relative to the scan root; passed back in `include`. */
	key: string,
	/**  Display name ("Downloads", "App containers"). */
	label: string,
};

/**  A finished report's summary. */
export type SpaceReport = {
	id: number,
	volume: SpaceVolume,
	finished_ms: number | null,
	duration_ms: number | null,
	items: number | null,
	used_bytes: number | null,
	/**  Measured in files on the scanned volume. */
	files_bytes: number | null,
	/**  Other volumes in the container. */
	volumes_bytes: number | null,
	/**
	 *  Used space not attributed to files or volumes; `None` when files exceed it
	 *  (APFS clones counted for each copy).
	 */
	other_bytes: number | null,
	unreadable: number,
	/**  The first unreadable folders, relative to the volume root. */
	unreadable_paths: string[],
	/**  Labels of protected locations that were skipped. */
	skipped: string[],
	/**  The tree hit its retention cap: deep breakdowns are folded, totals are complete. */
	truncated: boolean,
};

/**  Progress of the current (or last) scan. Polled while a scan runs. */
export type SpaceScanStatus = {
	phase: SpacePhase,
	/**  Report id of the scan this describes; queries use it. */
	report_id: number | null,
	volume: string | null,
	elapsed_ms: number | null,
	/**  Files counted so far. */
	items: number | null,
	/**  Bytes measured in files so far. */
	measured_bytes: number | null,
	/**  The volume's used bytes, the denominator for progress ("about 62%"). */
	used_bytes: number | null,
	/**  The folder being read, relative to the volume root. Absent when not scanning. */
	current: string | null,
	error: string | null,
};

/**  A folder and its largest entries, sorted largest first, with merges applied. */
export type SpaceSubtree = {
	folder: SpaceNode,
	/**  From the volume root to this folder, inclusive. */
	path: SpaceCrumb[],
	children: SpaceNode[],
	/**
	 *  While the folder is unfinished: its total not yet attributed to a finished entry.
	 *  At the volume root this is measured against the volume's used bytes.
	 */
	unmeasured_bytes: number | null,
	/**  The total the breakdown is drawn against (folder bytes, or used bytes at the root). */
	total_bytes: number | null,
};

/**  What `disk_space_reveal` shows in Finder. */
export type SpaceTarget = { kind: "node"; id: number } | { kind: "largest_file"; index: number };

/**  A volume the user can scan, as Finder shows it. */
export type SpaceVolume = {
	/**  The browsable mount point ("/" for the boot volume). Used as the volume's id. */
	mount: string,
	/**  Finder's name ("Macintosh HD"). */
	name: string,
	is_boot: boolean,
	/**  Used space Finder reports for the volume (its APFS container for APFS volumes). */
	used_bytes: number | null,
	total_bytes: number | null,
	/**  Locations macOS protects with privacy prompts. Skipped unless included by key. */
	protected: SpaceProtected[],
};

/**  A process as the store keeps it: fewer fields than [`LiveProcess`]. */
export type StoredProcess = {
	name: string,
	pid: number,
	cpu_pct: number | null,
	mem_bytes: number,
	threads: number,
	idle_wakeups_per_s: number | null,
	energy: number | null,
};

/**  What `subscribe_live` did before returning. */
export type SubscriptionInfo = {
	host: HostId,
	/**
	 *  This subscription's id (the channel's): pass it to `set_process_interest` so the
	 *  interest belongs to this page load and ends with it.
	 */
	stream: number,
	/**
	 *  Start of the backfill already sent on the channel, `null` when none was (the ring is
	 *  empty, or the window is hidden and the channel starts when it is shown).
	 */
	backfill_start_ms: number | null,
	/**  Backfill rows sent, over all segments. */
	backfill_rows: number,
	/**
	 *  Start of the older history that follows as `BackfillEarlier` chunks, `null` when
	 *  none does.
	 */
	earlier_start_ms: number | null,
	/**  Rows still to come in `BackfillEarlier` chunks. */
	earlier_rows: number,
};

export type TemperatureUnit = "celsius" | "fahrenheit";

/**
 *  `NSProcessInfo.thermalState`, the value of the `thermal.state` metric. Ordered, so
 *  `state >= ThermalState::Serious` reads naturally.
 */
export type ThermalState = "nominal" | "fair" | "serious" | "critical";

/**
 *  A resolution of data. [`Tier::S10`], [`Tier::M1`] and [`Tier::M15`] are persisted and
 *  synced; [`Tier::Live1s`] is the in-memory ring buffer and the live stream. M1 keeps the
 *  last 7 days; older minutes are rolled down into M15 for the rest of the retention.
 */
export type Tier = "live1s" | "s10" | "m1" |
/**
 *  15-minute buckets: minutes older than the M1 window, rolled down by the store.
 *  Older peers decode it as [`Tier::Unknown`] (D-040); it is synced only when both
 *  sides negotiated [`SyncRowKind::M15`].
 */
"m15" |
/**
 *  A tier this build does not know, named by a newer peer (D-040). It has no bucket
 *  width and is never persisted; a sync request for it is answered with an error.
 */
"unknown";

/**  Which tier `query_history` reads. */
export type TierRequest =
/**
 *  10 s buckets while they cover the start of the range (24 h); otherwise 1 min while
 *  minutes cover it (7 days), else 15 min.
 */
"auto" | "s10" | "m1";

export type UnitSettings = {
	temperature: TemperatureUnit,
	network: NetworkUnit,
	memory: MemoryUnit,
};

export type UnitsPatch = {
	temperature?: TemperatureUnit | null,
	network?: NetworkUnit | null,
	memory?: MemoryUnit | null,
};

export type UnsupportedReason =
/**  The sensor map does not know this chip yet ("Share sensor dump"). */
"unknown_chip" |
/**
 *  The build cannot hold the entitlement the collector needs ("not available in this
 *  edition").
 */
"missing_entitlement" |
/**  The API is there but reports no such hardware. */
"no_hardware" |
/**
 *  The hardware is there but this process may not read it: RAPL energy files are
 *  root-only on Linux, and the agent may run unprivileged (D-115).
 */
"permission_denied" |
/**
 *  A reason this build does not know (D-040). The UI shows a generic
 *  "not available".
 */
"unknown";

export type UpdateStatus = { kind: "idle" } | { kind: "not_configured" } | { kind: "checking" } | { kind: "up_to_date" } | { kind: "available"; version: string; notes: string } | { kind: "downloading"; version: string; percent: number | null } | { kind: "installing"; version: string } | { kind: "ready"; version: string } | { kind: "failed"; message: string };

export type UpdateStatusChanged = {
	status: UpdateStatus,
};

/**
 *  `query_usage_by_app`: which apps used CPU, GPU, memory, disk and energy over a range,
 *  from the last hour of process samples Kelvo keeps in memory (D-093, D-099). Your
 *  processes only; `other` holds the rest.
 */
export type UsageByApp = {
	/**  The range the sums cover: the request widened to whole 10 s buckets. */
	from_ms: number,
	to_ms: number,
	/**
	 *  When Kelvo started counting (this launch, or the last history clear); `null`
	 *  before the first process sample. After `from_ms`, the range is covered only from
	 *  here.
	 */
	since_ms: number | null,
	/**
	 *  Buckets ending at or before this no longer change; a range reaching past it is
	 *  still being measured. `null` before the first process sample.
	 */
	complete_to_ms: number | null,
	/**
	 *  Time inside the range a process sample covered, ms. Averages divide by it; 0 means
	 *  not measured, not zero use.
	 */
	covered_ms: number,
	/**  The part of `covered_ms` whose samples measured GPU. */
	gpu_covered_ms: number,
	total: UsageTotal,
	other: UsageOther,
	/**  The largest `limit` by the requested key, largest first. */
	apps: AppUsage[],
};

/**  What `query_usage_by_app` sorts apps by (D-099). */
export type UsageKey =
/**  Average CPU. */
"cpu" |
/**  Average GPU. */
"gpu" |
/**  Peak footprint. */
"memory" |
/**  Bytes read plus written. */
"disk" |
/**  Joules. */
"energy";

/**
 *  What the host measured beyond Kelvo's processes ("System and other"): the host's
 *  own series over the same range less `UsageByApp.total`. It holds other users' and
 *  root's processes and those that lived less than one sample. `null` fields where the
 *  series was not recorded (module off, GPU never measured).
 */
export type UsageOther = {
	/**  Percent of one core: `cpu.total` times the cores, less the apps. */
	cpu_avg_pct: number | null,
	/**  `gpu.util` less the apps. */
	gpu_avg_pct: number | null,
	/**  `disk.read_total` bytes less the apps'. */
	read_bytes: number | null,
	write_bytes: number | null,
	/**
	 *  The keys whose remainder was clamped to 0: the apps exceeded the host total
	 *  there (the two are sampled differently).
	 */
	clamped: UsageKey[],
};

/**  Every process's use over the range, before any floor: what shares are of. */
export type UsageTotal = {
	cpu_avg_pct: number | null,
	gpu_avg_pct: number | null,
	read_bytes: number | null,
	write_bytes: number | null,
	energy_j: number | null,
	avg_w: number | null,
};

/**
 *  What every window root reflects as attributes: `data-performance`,
 *  `data-reduce-transparency` and the theme.
 */
export type WindowAppearance = {
	/**
	 *  Whether Performance mode is in effect, and why (D-088). Any reason but `off`
	 *  turns all motion off.
	 */
	performance: PerformanceReason,
	/**  The macOS Reduce Transparency accessibility setting. */
	reduce_transparency: boolean,
	/**
	 *  The user's Appearance setting. `system` follows `prefers-color-scheme`; Rust also
	 *  sets the native window theme, so vibrancy and the CSS media query agree.
	 */
	theme: Appearance,
};

/**  Emitted when Performance mode, Reduce Transparency or the theme changes. */
export type WindowAppearanceChanged = {
	appearance: WindowAppearance,
};

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

